package jp.co.questcom.droidshooting.application;

public class GameItems extends Main implements SensorEventListener {
    private static final float LOW_PATH_FILTER_VALUE = 0.2f;
    private static final int MATRIX_SIZE = 16;
    private static Context mContext;
    private GameDisplayView gameDisplayView;
    private boolean mIsAccSensor;
    private boolean mIsMagSensor;
    private SensorManager sensorManager;
    float[] inR = new float[MATRIX_SIZE];
    float[] outR = new float[MATRIX_SIZE];
    float[] I = new float[MATRIX_SIZE];
    private float[] orientationValues = new float[3];
    private float[] magneticValues = new float[3];
    private float[] accelerometerValues = new float[3];
    private float[] currentOrientationValues = {0.0f, 0.0f, 0.0f};
    private float[] currentRadianToDegreeOrientationValues = {0.0f, 0.0f, 0.0f};
    private List<SensorChangeEventListner> listners = new ArrayList();

    public interface SensorChangeEventListner {
        void onSensorChanged(float[] fArr, float[] fArr2);
    }

    @Override // jp.co.questcom.droidshooting.Main, android.app.Activity
    public void onCreate(Bundle savedInstanceState) {
        showDialog(0);
        super.onCreate(savedInstanceState);
        GameResources.InitializeGame(this, GetResorces());
        this.gameDisplayView = new GameDisplayView(this, getIntent().getLongExtra("jp.co.questcom.droidshooting.stage", 0L), getIntent().getLongExtra("jp.co.questcom.droidshooting.score", 0L));
        addSensorChangeEventListner(this.gameDisplayView);
        GLView glview = new GLView(this);
        addSensorChangeEventListner(glview);
        setContentView(glview, new LinearLayout.LayoutParams(-1, -1));
        addContentView(this.gameDisplayView, new LinearLayout.LayoutParams(-1, -1));
        this.sensorManager = (SensorManager) getSystemService("sensor");
        mContext = getApplicationContext();
    }

    @Override // android.app.Activity
    public void onResume() {
        super.onResume();
        Log.i("EVENT_TEST", "onResume");
        List<Sensor> sensors = this.sensorManager.getSensorList(-1);
        for (Sensor sensor : sensors) {
            if (sensor.getType() == 2) {
                this.sensorManager.registerListener(this, sensor, 1);
                this.mIsMagSensor = true;
            }
            if (sensor.getType() == 1) {
                this.sensorManager.registerListener(this, sensor, 1);
                this.mIsAccSensor = true;
            }
        }
    }

    @Override // android.app.Activity
    protected void onPause() {
        super.onPause();
        Log.i("EVENT_TEST", "onPause");
        if (this.mIsMagSensor || this.mIsAccSensor) {
            this.sensorManager.unregisterListener(this);
            this.mIsMagSensor = false;
            this.mIsAccSensor = false;
        }
        this.gameDisplayView.onPause();
    }

    @Override // android.hardware.SensorEventListener
    public void onSensorChanged(SensorEvent event) {
        switch (event.sensor.getType()) {
            case 1:
                this.accelerometerValues = (float[]) event.values.clone();
                break;
            case 2:
                this.magneticValues = (float[]) event.values.clone();
                break;
        }
        if (this.magneticValues != null && this.accelerometerValues != null) {
            SensorManager.getRotationMatrix(this.inR, this.I, this.accelerometerValues, this.magneticValues);
            SensorManager.remapCoordinateSystem(this.inR, 1, 131, this.outR);
            SensorManager.getOrientation(this.outR, this.orientationValues);
            orientCalc(this.orientationValues);
            for (SensorChangeEventListner listner : this.listners) {
                listner.onSensorChanged(this.orientationValues, this.currentRadianToDegreeOrientationValues);
            }
        }
    }

    private int radianToDegree(float rad) {
        return (int) Math.floor(Math.toDegrees(rad));
    }

    private void orientCalc(float[] values) {
        float azimuth = radianToDegree(values[0]) + 180.0f;
        float pitch = radianToDegree(values[1]);
        float roll = radianToDegree(values[2]);
        boolean isAdd = false;
        if (azimuth < 40.0f && this.currentRadianToDegreeOrientationValues[0] > 320.0f) {
            azimuth += 360.0f;
            isAdd = true;
        } else if (azimuth > 320.0f && this.currentRadianToDegreeOrientationValues[0] < 40.0f) {
            float[] fArr = this.currentRadianToDegreeOrientationValues;
            fArr[0] = fArr[0] + 360.0f;
            isAdd = true;
        }
        float tmpX = (azimuth * LOW_PATH_FILTER_VALUE) + (this.currentRadianToDegreeOrientationValues[0] * 0.8f);
        if (isAdd && tmpX > 360.0f) {
            tmpX -= 360.0f;
        }
        this.currentRadianToDegreeOrientationValues[0] = tmpX;
        this.currentRadianToDegreeOrientationValues[1] = (pitch * LOW_PATH_FILTER_VALUE) + (this.currentRadianToDegreeOrientationValues[1] * 0.8f);
        this.currentRadianToDegreeOrientationValues[2] = roll;
    }

    @Override // android.hardware.SensorEventListener
    public void onAccuracyChanged(Sensor sensor, int accuracy) {
    }

    public static boolean isDebug() {
        PackageManager manager = mContext.getPackageManager();
        try {
            ApplicationInfo appInfo = manager.getApplicationInfo(mContext.getPackageName(), 0);
            return (appInfo.flags & 2) == 2;
        } catch (PackageManager.NameNotFoundException e) {
            return false;
        }
    }

    public static float radToDeg(float rad) {
        return (float) ((180.0f * rad) / 3.141592653589793d);
    }

    public void hideDialog() {
        try {
            dismissDialog(0);
            removeDialog(0);
        } catch (IllegalArgumentException e) {
        }
    }

    @Override // android.app.Activity
    protected Dialog onCreateDialog(int id) {
        switch (id) {
            case 0:
                ProgressDialog dialog = new ProgressDialog(this);
                dialog.setMessage("Now Loading ...");
                dialog.setCancelable(false);
                return dialog;
            default:
                return super.onCreateDialog(id);
        }
    }

    @Override // android.app.Activity
    public void finish() {
        CameraActivity.finishActivity();
        super.finish();
    }

    @Override // jp.co.questcom.droidshooting.Main, android.app.Activity
    public boolean onOptionsItemSelected(MenuItem item) {
        switch (item.getItemId()) {
            case 0:
                this.gameDisplayView.selectMenuVibration();
                item.setIcon(this.gameDisplayView.isVibration() ? R.drawable.icon_vibration_on : R.drawable.icon_vibration_off);
                break;
            case 1:
                this.gameDisplayView.selectMenuMusic();
                item.setIcon(this.gameDisplayView.isMusin() ? R.drawable.icon_music_on : R.drawable.icon_music_off);
                break;
            case 2:
                this.gameDisplayView.selectMenuSounds();
                item.setIcon(this.gameDisplayView.isSounds() ? R.drawable.icon_sounds_on : R.drawable.icon_sounds_off);
                break;
        }
        return true;
    }

    public void addSensorChangeEventListner(SensorChangeEventListner listner) {
        this.listners.add(listner);
    }

    public void removeSensorChangeEventListner(SensorChangeEventListner listner) {
        this.listners.remove(listner);
    }
}

