        StageSelectView scoreList = new StageSelectView(this, 0, 0);
        scoreList.setOnArrowButtonEventListner(this);
        scoreList.setOnIconClickEventListner(this);
        scoreList.addView(scoreListLayout);
        this.stageSelectViewAdapter.addView(scoreList);
        this.titleView = new TitleView(this, this.stageSelectBackgroundView);
        this.title = new StageSelectView(this, 1, 1);
        this.title.setOnArrowButtonEventListner(this);
        this.title.setOnIconClickEventListner(this);
        this.title.addView(this.titleView);
        this.listners.add(this.title);
        this.stageSelectViewAdapter.addView(this.title);
        this.maxStageNumber = Score.selectMaxStageNumber() + 1;
        for (int i = 0; i < this.maxStageNumber + 1; i++) {
            addStageSelectView(i);
        }
        this.gallery.setSelection(1);
        this.stageSelectViewAdapter.notifyDataSetChanged();
        this.rogoView = new RogoView(this);
        addContentView(this.rogoView, new ViewGroup.LayoutParams(-1, -1));
    }

