    public void onShareClick() {
        Member me = Member.getMe();
        Long wholeScore = 0L;
        long maxStage = Score.selectMaxStageNumber();
        for (long i = 0; i <= maxStage; i++) {
            Score[] scores = Score.selectByStageAsScoreArray(i);
            wholeScore = Long.valueOf(wholeScore.longValue() + scores[0].getScore());
        }
        Intent intent = new Intent("android.intent.action.SEND");
        intent.setType(HttpRequestHelper.MIME_TEXT_PLAIN);
        if (me == null) {
            intent.putExtra("android.intent.extra.TEXT", getString(R.string.share_not_play));
