    public static double CalcTurningAngle(Point startingPoint, Point oldPoint, Point targetPoint) {
        float vaX = oldPoint.getX() - startingPoint.getX();
        float vaY = oldPoint.getY() - startingPoint.getY();
        float vaZ = oldPoint.getZ() - startingPoint.getZ();
        float vbX = targetPoint.getX() - startingPoint.getX();
        float vbY = targetPoint.getY() - startingPoint.getY();
        float vbZ = targetPoint.getZ() - startingPoint.getZ();
        double denominator = Math.sqrt((Math.pow(vaX, 2.0d) + Math.pow(vaY, 2.0d) + Math.pow(vaZ, 2.0d)) * (Math.pow(vbX, 2.0d) + Math.pow(vbY, 2.0d) + Math.pow(vbZ, 2.0d)));
        double molecule = (vbZ * vaZ) + (vaX * vbX) + (vaY * vbY);
        double dividing = molecule / denominator;
        if (1.0d < dividing) {
            dividing = 1.0d;
        } else if (dividing < -1.0d) {
            dividing = -1.0d;
        }
        double ret = (Math.acos(dividing) / 3.141592653589793d) * 180.0d;
        return ret;
    }

