        float xDistance = Math.abs(next.getX() - current.getX());
        float yDistance = Math.abs(next.getY() - current.getY());
        float zDistance = Math.abs(next.getZ() - current.getZ());
        float allDistance = xDistance + yDistance + zDistance;
        if (allDistance == 0.0f) {
            return new Point(next.getX(), next.getY(), next.getZ());
        }
        float xRatio = xDistance / allDistance;
        float yRatio = yDistance / allDistance;
        float zRatio = zDistance / allDistance;
        float xMovable = movablePixels * xRatio;
        float yMovable = movablePixels * yRatio;
        float zMovable = movablePixels * zRatio;
        float movablePixels2 = current.getX();
        float zRatio2 = next.getX();
        if (zRatio2 <= current.getX()) {
            xMovable = -xMovable;
        }
        float x2 = movablePixels2 + xMovable;
        float y2 = current.getY();
        if (next.getY() <= current.getY()) {
            yMovable = -yMovable;
        }
        float y3 = y2 + yMovable;
        float z2 = current.getZ();
        if (next.getZ() <= current.getZ()) {
            zMovable = -zMovable;
        }
        float z3 = z2 + zMovable;
        if (!reviseOverflow || xDistance > Math.abs(x2 - current.getX()) || yDistance > Math.abs(y3 - current.getY()) || zDistance > Math.abs(z3 - current.getZ())) {
            z = y3;
            x = x2;
            y = z3;
        } else {
            x = next.getX();
            float y4 = next.getY();
            float z4 = next.getZ();
            z = y4;
            y = z4;
        }
        return new Point(x, z, y);
    }

