    private void drawGameOver(Canvas canvas) {
        Bitmap numBmp;
        if (this.gameStatus == 2) {
            if (this.startTime == 0) {
                this.gameViewBase.pauseBGM();
                this.startTime = System.currentTimeMillis();
                for (GameEventListner listner : gameEventListners) {
                    listner.onGameOver();
                }
                this.startTime = System.currentTimeMillis();
            }
            if (System.currentTimeMillis() - this.startTime > 1000) {
                addSound(4, SE_VOLUME_EXPLOSION_LARGE, SE_VOLUME_EXPLOSION_LARGE, 1, 0, SE_VOLUME_EXPLOSION_LARGE);
                this.startTime = 0L;
                this.gameStatus = 3;
            }
            drawItems(canvas);
            return;
        }
        float locateY_1 = (GameResources.displayHeight / 3) + 40;
        float f = GameResources.displayHeight - (GameResources.displayHeight / 3);
        if (this.startTime == 0) {
            this.startTime = System.currentTimeMillis();
        }
        canvas.drawBitmap(GameResources.timeIsUp, GameResources.centerX - (GameResources.timeIsUp.getWidth() / 2), locateY_1, (Paint) null);
        drawBitmapOnCanvas(GameResources.wave, GameResources.centerX - ((GameResources.wave.getWidth() / 3) * 2), (GameResources.centerY - 80) - GameResources.wave.getHeight(), (Paint) null, canvas);
        DecimalFormat formatWave = new DecimalFormat("00");
        char[] roundNumberArray = String.valueOf(formatWave.format(this.stageCount)).toCharArray();
        boolean isShowZero = false;
        for (int i = 0; i < roundNumberArray.length; i++) {
            int num = Integer.parseInt(String.valueOf(roundNumberArray[i]));
            if (num > 0) {
                isShowZero = true;
                numBmp = GameResources.numbers[num];
            } else if (isShowZero) {
                numBmp = GameResources.numbers[0];
            } else {
                numBmp = GameResources.numbers[10];
            }
            if (numBmp != null) {
                drawBitmapOnCanvas(numBmp, GameResources.centerX + 20 + numBmp.getWidth() + (numBmp.getWidth() * i), (GameResources.centerY - 80) - numBmp.getHeight(), (Paint) null, canvas);
            }
        }
        drawBitmapOnCanvas(GameResources.menuTryAgain, this.gameOverTryAgainButtonPoint.x, this.gameOverTryAgainButtonPoint.y, (Paint) null, canvas);
        drawBitmapOnCanvas(GameResources.menuReturnWaveSelect, this.gameOverReturnWaveSelectButtonPoint.x, this.gameOverReturnWaveSelectButtonPoint.y, (Paint) null, canvas);
        this.gameStatus = 4;
    }

package jp.co.questcom.droidshooting.common;

    private void drawItems(Canvas canvas) {
        canvas.save();
        drawBitmapOnCanvas(GameResources.shootButton, this.shootButtonPoint.x, this.shootButtonPoint.y, (Paint) null, canvas);
        canvas.save();
        if (this.changeButtonRotateDegree < 0.0f && this.changeButtonRotateDegree >= -180.0f) {
            this.changeButtonRotateDegree -= CHANGE_BUTTON_ROTATE_DEGREE;
            canvas.rotate(this.changeButtonRotateDegree, this.weaponChangeButtonPoint.x + (GameResources.weaponChangeButton.getWidth() / 2), this.weaponChangeButtonPoint.y + (GameResources.weaponChangeButton.getHeight() / 2));
        }
        drawBitmapOnCanvas(GameResources.weaponChangeButton, this.weaponChangeButtonPoint.x, this.weaponChangeButtonPoint.y, (Paint) null, canvas);
        canvas.restore();
        if (this.stageCount - 1 < 3 && this.time > 55000) {
            canvas.save();
            drawBitmapOnCanvas(GameResources.messageWeaponChange, (this.weaponChangeButtonPoint.x - GameResources.messageWeaponChange.getWidth()) + (GameResources.weaponChangeButton.getWidth() / 2), this.weaponChangeButtonPoint.y - GameResources.messageWeaponChange.getHeight(), (Paint) null, canvas);
            canvas.restore();
        }
        canvas.save();
        drawTime(canvas);
        canvas.restore();
    }

package jp.co.questcom.droidshooting.common;

    private void drawRaderPoint(Canvas canvas) {
        Bitmap bitmap;
        canvas.save();
        canvas.rotate(this.azimuth * (-1.0f), this.slideLengthX, this.slideLengthY);
        if (GameObjectManager.getInstance() != null) {
            this.objList = GameObjectManager.getInstance().getDrawGameObjects();
            for (GameObject obj : this.objList) {
                if (obj.isAlive() && obj.getRaderDrawType() != 0) {
                    this.point = obj.getCurrentPosition();
                    if (this.point.getY() > 10.0f) {
                        bitmap = obj.getRaderDrawType() == 3 ? GameResources.raderPointRedMini : GameResources.raderPointRed;
                    } else if (this.point.getY() > 5.0f) {
                        bitmap = obj.getRaderDrawType() == 3 ? GameResources.raderPointOrangeMini : GameResources.raderPointOrange;
                    } else if (this.point.getY() < -10.0f) {
                        bitmap = obj.getRaderDrawType() == 3 ? GameResources.raderPointBlueMini : GameResources.raderPointBlue;
                    } else if (this.point.getY() < -5.0f) {
                        bitmap = obj.getRaderDrawType() == 3 ? GameResources.raderPointSkyBlueMini : GameResources.raderPointSkyBlue;
                    } else {
                        bitmap = obj.getRaderDrawType() == 3 ? GameResources.raderPointYellowMini : GameResources.raderPointYellow;
                    }
                    Bitmap paintPoint = bitmap;
                    drawBitmapOnCanvas(paintPoint, (this.point.getX() * DISTANCE_ENEMY_ATTACK) + this.slideLengthX, (this.point.getZ() * DISTANCE_ENEMY_ATTACK) + this.slideLengthY, (Paint) null, canvas);
                }
            }
        }
        canvas.restore();
    }

