    private void drawStageClear(Canvas canvas) {
        Bitmap numBmp;
        Bitmap numBmp2;
        if (this.gameStatus == 7) {
            if (this.startTime == 0) {
                this.gameViewBase.pauseBGM();
                addSound(3, SE_VOLUME_EXPLOSION_LARGE, SE_VOLUME_EXPLOSION_LARGE, 1, 0, SE_VOLUME_EXPLOSION_LARGE);
                this.startTime = System.currentTimeMillis();
                for (GameEventListner listner : gameEventListners) {
                    listner.onStageEnd(this.stageCount);
                }
                this.highScores = null;
            }
            if (System.currentTimeMillis() - this.startTime > 1000) {
                this.startTime = 0L;
                this.gameStatus = 8;
            }
            drawItems(canvas);
            return;
        }
        GameObjectManager.getInstance().suspend();
        if (this.time >= 1000) {
            if (this.startTime == 0) {
                this.startTime = System.currentTimeMillis();
            }
            if (this.time > 0 && System.currentTimeMillis() - this.startTime > 1000) {
                this.plusScore = Long.valueOf((this.time / BOUNS_SCORE_CALC_BASE) * BOUNS_SCORE_TIME_REMAING);
                this.score += this.plusScore.longValue();
                this.tempRemainingTime = this.time;
                this.time = 0L;
                this.startTime = 0L;
            }
            drawScore(canvas);
        } else {
            this.time = 0L;
            if (this.startTime == 0) {
                this.startTime = System.currentTimeMillis();
                saveScore();
            }
            if (System.currentTimeMillis() - this.startTime > 1000) {
                drawBitmapOnCanvas(GameResources.menuToNextWave, this.toNextWaveButtonPoint.x, this.toNextWaveButtonPoint.y, (Paint) null, canvas);
                drawBitmapOnCanvas(GameResources.menuTryAgain, this.tryAgainButtonPoint.x, this.tryAgainButtonPoint.y, (Paint) null, canvas);
