    public void drawCanvas(Canvas canvas, float roll, float azimuth) {
        float degree = roll + 90.0f;
        canvas.drawARGB(0, 0, 0, 0);
        setVibrationDistance();
        this.roll = roll;
        this.azimuth = azimuth;
        for (GameEventListner listner : gameEventListners) {
            listner.onDrawGame(canvas, degree, this.vibrationX, this.vibrationY);
        }
        if (System.currentTimeMillis() > this.enemyAttackEffectStartTime + 1000) {
            this.enemyAttackEffectStartTime = 0L;
        }
        switch (this.gameStatus) {
            case 1:
                this.gameViewBase.initBGM(this.gameItems, R.raw.airf);
                this.startTime = 0L;
                this.gameStatus = 5;
                for (GameEventListner listner2 : gameEventListners) {
                    listner2.onGameStart();
                }
                break;
            case 2:
            case 3:
            case 4:
                drawGameOver(canvas);
                break;
            case 5:
                if (this.startTime == 0) {
                    this.startTime = System.currentTimeMillis();
                    for (GameEventListner listner3 : gameEventListners) {
                        listner3.onStageStart(this.stageCount);
                    }
                    this.score = 0L;
                    Title.currentStageNumber = this.stageCount;
                    this.changeButtonRotateDegree = 0.0f;
                    break;
                } else if (System.currentTimeMillis() - this.startTime > 2000) {
                    GameObjectManager.getInstance().startStage(this.stageCount);
                    this.stageCount++;
                    this.gameStatus = 6;
                    this.stageStartTime = 0L;
                    ParticleManager.initialize();
                    break;
                } else {
                    drawStageCount(canvas);
                    break;
                }
            case 6:
                if (this.stageStartTime == 0) {
                    this.stageStartTime = System.currentTimeMillis();
                }
                culcRemainingTime();
                if (this.time <= 0) {
                    this.gameStatus = 2;
                    this.startTime = 0L;
                }
                drawItems(canvas);
                for (GameEventListner listner4 : gameEventListners) {
                    listner4.onPlayingStage(this.stageCount);
                }
                judgeEnemyAttack(canvas);
                boolean isAliveEnemy = false;
                Iterator<GameObject> it = GameObjectManager.getInstance().getAliveEnemyGameObjects().iterator();
                while (true) {
                    if (it.hasNext()) {
                        GameObject obj = it.next();
                        if (!(obj instanceof EnemyBulletObject)) {
                            isAliveEnemy = true;
                        }
                    }
                }
                if (!isAliveEnemy) {
                    this.gameStatus = 7;
                    this.startTime = 0L;
                    break;
                }
                break;
            case 7:
            case 8:
            case 9:
                if (this.gameStatus == 7) {
                    for (GameEventListner listner5 : gameEventListners) {
                        listner5.onPlayingStage(this.stageCount);
                    }
                }
                drawStageClear(canvas);
                break;
        }
        if (this.enemyAttackEffectStartTime <= 0) {
            canvas.drawARGB(0, 0, 0, 0);
        }
        canvas.save();
        canvas.rotate(degree, (GameResources.rader.getWidth() / 2) + 10.0f, (GameResources.rader.getHeight() / 2) + 10.0f);
        drawBitmapOnCanvas(GameResources.rader, 10.0f, 10.0f, (Paint) null, canvas);
        drawRaderPoint(canvas);
        canvas.restore();
        canvas.save();
        drawScore(canvas);
        canvas.restore();
        canvas.save();
        drawDamageSec(canvas);
        canvas.restore();
        for (GameSound gameSound : GameSound.getGameSound()) {
            this.gameViewBase.playSound(gameSound);
        }
        GameSound.clear();
        if (this.vibrateTime > 0) {
            this.gameViewBase.callVibrator(this.vibrateTime);
        }
        this.vibrateTime = -1;
    }

    private void judgeEnemyAttack(Canvas canvas) {
        float currentDisplayY = GameResources.displayHeight - DAMAGE_DISPLAY_Y_FROM_BOTTOM;
        try {
            for (GameObject obj : GameObjectManager.getInstance().getDrawGameObjects()) {
                if (obj.isAlive() && CoordinatesCalculationUtil.getVectorLength(obj.getCurrentPosition(), new Point(0.0f, 0.0f, 0.0f)) <= (DISTANCE_ENEMY_ATTACK * obj.getSize()) / 3.0f) {
                    GameObjectManager.getInstance().createHitEvent(obj, ENEMY_ATTACK_DAMAGE_TO_ENEMY);
                    this.gameViewBase.callVibrator(140L);
                    this.enemyAttackEffectStartTime = System.currentTimeMillis();
                    addSound(12, SE_VOLUME_EXPLOSION_LARGE, SE_VOLUME_EXPLOSION_LARGE, 1, 0, SE_VOLUME_EXPLOSION_LARGE);
                    this.stageStartTime -= SHOW_WEAPON_CHANGE_MESSAGE_TIME;
                    int i = this.nowDispDamageIndex + 1;
                    this.nowDispDamageIndex = i;
                    this.nowDispDamageIndex = i % 10;
                    damageDisps[this.nowDispDamageIndex].initialize(5, currentDisplayY);
                    this.vibrationStartTime = System.currentTimeMillis();
                    for (GameEventListner listner : gameEventListners) {
                        listner.onDamageAtEnemyAttack();
                    }
                }
            }
        } catch (ConcurrentModificationException e) {
        }
    }

