    private void saveScore() {
        Integer baseScore = GameResources.getBaseScore(this.stageCount - 1, this.gameItems.getResources());
        Score.Medal medal = Score.Medal.BRONZE;
        if (baseScore == null || baseScore.intValue() < this.score) {
            medal = Score.Medal.GOLD;
        } else if (baseScore.intValue() * 0.9d < this.score) {
            medal = Score.Medal.SILVER;
        }
        Log.d("Save_Score", "CurrentScore    : " + this.score);
        Log.d("Save_Score", "BaseScore       : " + baseScore);
        Log.d("Save_Score", "BaseScore * 0.9 : " + (baseScore.intValue() * 0.9d));
        Log.d("Save_Score", "Medal           : " + medal.name());
        Score s = new Score(this.score, this.stageCount - 1, this.tempRemainingTime, medal);
        s.save();
        Intent intent = new Intent(this.gameItems, (Class<?>) SaveIntentService.class);
        this.gameItems.startService(intent);
    }

    public static String getStringDigest(String str) throws NoSuchAlgorithmException {
        StringBuilder hex = new StringBuilder();
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(str.getBytes());
        byte[] digest = md.digest();
        for (int i = 0; i < digest.length; i++) {
            if ((digest[i] & 255) < 16) {
                hex.append("0");
            }
            hex.append(Integer.toHexString(digest[i] & 255));
        }
        return hex.toString();
    }

    private float getVolume(Point point, float baseVolume) {
        float distance = Math.abs(point.getX()) + Math.abs(point.getY()) + Math.abs(point.getZ());
        float distanceVolume = (SE_VOLUME_AJUSTMENT - distance) * 0.8f <= 0.3f ? 0.3f : (SE_VOLUME_AJUSTMENT - distance) * 0.8f;
        if (distanceVolume >= baseVolume) {
            distanceVolume = baseVolume;
        }
        return baseVolume * distanceVolume;
    }

