    public void setVibrationDistance() {
        if (this.vibrationStartTime <= 0) {
            this.vibrationStartTime = 0L;
            this.vibrationX = 0.0f;
            this.vibrationY = 0.0f;
        } else if (System.currentTimeMillis() < this.vibrationStartTime + 1000) {
            float ratio = SE_VOLUME_EXPLOSION_LARGE - ((System.currentTimeMillis() - this.vibrationStartTime) / 1000.0f);
            this.vibrationX = (this.vibrationX > 0.0f ? -15.0f : 15.0f) * ratio * (this.rand.nextInt(10) / 2 == 0 ? -1 : 1);
            this.vibrationY = (this.vibrationY > 0.0f ? -15.0f : 15.0f) * ratio * (this.rand.nextInt(10) / 2 == 0 ? -1 : 1);
        } else {
            this.vibrationStartTime = 0L;
            this.vibrationX = 0.0f;
            this.vibrationY = 0.0f;
        }
    }
