                        if (event.getY() >= this.toNextWaveButtonPoint.y && event.getY() <= this.toNextWaveButtonPoint.y + GameResources.menuToNextWave.getHeight() && event.getX() >= this.toNextWaveButtonPoint.x && event.getX() <= this.toNextWaveButtonPoint.x + GameResources.menuToNextWave.getWidth()) {
                            this.gameStatus = 5;
                            this.startTime = 0L;
                            break;
                        } else if (event.getY() >= this.tryAgainButtonPoint.y && event.getY() <= this.tryAgainButtonPoint.y + GameResources.menuTryAgain.getHeight() && event.getX() >= this.tryAgainButtonPoint.x && event.getX() <= this.tryAgainButtonPoint.x + GameResources.menuTryAgain.getWidth()) {
                            this.gameStatus = 5;
                            this.startTime = 0L;
                            this.stageCount--;
                            break;
                        } else if (event.getY() >= this.returnWaveSelectButtonPoint.y && event.getY() <= this.returnWaveSelectButtonPoint.y + GameResources.menuReturnWaveSelect.getHeight() && event.getX() >= this.returnWaveSelectButtonPoint.x && event.getX() <= this.returnWaveSelectButtonPoint.x + GameResources.menuReturnWaveSelect.getWidth()) {
                            this.gameItems.finish();
                            break;
                        }
                        break;
                }
            }
            if (this.gameStatus == 4) {
                switch (event.getAction()) {
                    case 0:
                        if (event.getY() >= this.gameOverTryAgainButtonPoint.y && event.getY() <= this.gameOverTryAgainButtonPoint.y + GameResources.menuTryAgain.getHeight() && event.getX() >= this.gameOverTryAgainButtonPoint.x && event.getX() <= this.gameOverTryAgainButtonPoint.x + GameResources.menuTryAgain.getWidth()) {
                            this.gameStatus = 5;
                            this.startTime = 0L;
                            this.stageCount--;
                            this.gameViewBase.playBGM();
                            break;
                        } else if (event.getY() >= this.gameOverReturnWaveSelectButtonPoint.y && event.getY() <= this.gameOverReturnWaveSelectButtonPoint.y + GameResources.menuReturnWaveSelect.getHeight() && event.getX() >= this.gameOverReturnWaveSelectButtonPoint.x && event.getX() <= this.gameOverReturnWaveSelectButtonPoint.x + GameResources.menuReturnWaveSelect.getWidth()) {
                            this.gameItems.finish();
                            break;
                        }
                        break;
                }
            }
            return;
        }
        switch (event.getAction()) {
            case 0:
                if (event.getX() > this.shootButtonPoint.x && event.getX() < this.shootButtonPoint.x + GameResources.shootButton.getWidth() && event.getY() > this.shootButtonPoint.y && event.getY() < this.shootButtonPoint.y + GameResources.shootButton.getHeight()) {
                    for (ShootButtonTouchListner listner : shootButtonTouchListners) {
                        listner.onShootButtonTouch();
