    private static List<ByteBuffer> extract(Bitmap bmp) {
        List<ByteBuffer> bbList = new ArrayList<>();
        ByteBuffer bb = ByteBuffer.allocateDirect(bmp.getWidth() * 128 * 4);
        IntBuffer ib = bb.asIntBuffer();
        int count = 0;
        for (int y = bmp.getHeight() - 1; y > -1; y--) {
            for (int x = 0; x < bmp.getWidth(); x++) {
                int pix = bmp.getPixel(x, (bmp.getHeight() - y) - 1);
                int alpha = (pix >> 24) & 255;
                int red = (pix >> 16) & 255;
                int green = (pix >> 8) & 255;
                int blue = pix & 255;
                ib.put((red << 24) | (green << 16) | (blue << 8) | alpha);
            }
            if (count == bmp.getWidth() - 1) {
                bb.position(0);
                bbList.add(0, bb);
                bb = ByteBuffer.allocateDirect(bmp.getWidth() * 128 * 4);
                ib = bb.asIntBuffer();
                count = 0;
            } else {
                count++;
            }
        }
        return bbList;
    }

