                    initEffect();
                    this.gameViewBase.playSound(8, 1.0f, 0.8f, 1, 0, 1.0f);
                    if (GameObjectManager.getInstance() != null) {
                        Point[] sightVecs = new Point[shotgunPointOfHit.length];
                        float azimuth = GLRenderer.getAzimuth();
                        float pitch = GLRenderer.getPitch();
                        for (int i = 0; i < shotgunPointOfHit.length; i++) {
                            PointOfHit pointOfHit = shotgunPointOfHit[i];
                            sightVecs[i] = new Point(getSightVector((pointOfHit.getPointX() / 10.0f) + azimuth, (pointOfHit.getPointY() / 10.0f) + pitch));
                        }
                        for (Point sightVec : sightVecs) {
                            List<GameObject> hitGameObject = GLRenderer.sortGameObject((ArrayList) GameObjectManager.getInstance().getInSightEnemyObjects(sightVec, this.shootgunHitDegree), true);
                            Iterator<GameObject> it = hitGameObject.iterator();
                            while (true) {
                                if (!it.hasNext()) {
                                    break;
                                }
                                GameObject obj = it.next();
                                if (obj.isAlive()) {
                                    GameObjectManager.getInstance().createHitEvent(obj);
                                }
                            }
                        }
                        this.shotgunCoolDownStartTime = System.currentTimeMillis();
                    }
                    if (this.shotgunRemainBullet > 0) {
                        this.shotgunRemainBullet--;
                        break;
                    }
                }
                break;
            case 2:
                for (int i2 = 0; i2 < 4; i2++) {
                    HomingLaserWeaponObject homingLaser = homingLasers[i2];
                    if (homingLaser != null && homingLaser.getStatus() == 2) {
                        this.gameViewBase.playSound(9, 0.7f, 0.7f, 1, 0, 1.0f);
                        homingLaser.shoot();
                        homingLasers[i2] = null;
                        this.homingLaserCoolDownStartTime = System.currentTimeMillis();
                    }
                }
                break;
            case 3:
                if (GameObjectManager.getInstance() != null) {
                    for (GameObject obj2 : GameObjectManager.getInstance().getDisplayObjects()) {
                        if (obj2.isAlive()) {
                            GameObjectManager.getInstance().createHitEvent(obj2);
                        }
                    }
                    break;
                }
                break;
        }
