    private void judgeInSightObject() {
        List<GameObject> objects = GameObjectManager.getInstance().getInSightEnemyObjects(new Point(GLRenderer.getSightVector()), MISSILE_SIGHT_DEFAULT_DEGREE);
        for (GameObject obj : objects) {
            if (!this.inSightGameObject.contains(obj)) {
                for (SightEventListner listner : this.listners) {
                    if (obj == this.targetObjectMap.get(listner)) {
                        listner.onInSight(obj);
                    }
                }
            } else {
                this.inSightGameObject.remove(obj);
            }
        }
        for (GameObject obj2 : this.inSightGameObject) {
            for (SightEventListner listner2 : this.listners) {
                if (obj2 == this.targetObjectMap.get(listner2)) {
                    listner2.onOutSight(obj2);
                }
            }
        }
        this.inSightGameObject = objects;
    }

