    private float[] getSightVector(float azimuth, float pitch) {
        double x_x = Math.sin(0.017453277777777776d * azimuth);
        double x_z = -Math.cos(0.017453277777777776d * azimuth);
        double y_y = Math.sin(0.017453277777777776d * pitch);
        double y_z = Math.cos(0.017453277777777776d * pitch);
        float[] sightVecs = {(float) (1.0d * x_x), (float) (1.0d * y_y), (float) (x_z * y_z)};
        return sightVecs;
    }

    @Override // jp.co.questcom.droidshooting.common.GameContoroller.ShootButtonTouchListner
    public void onShootButtonTouch() {
        switch (this.currentWeapon) {
            case 0:
                initEffect();
                this.gameViewBase.playSound(0, 0.5f, 0.4f, 1, 0, 1.0f);
                GLRenderer.HitJudgeRequest(GameResources.centerX, GameResources.centerY);
                break;
            case 1:
                if (this.shotgunCoolDownStartTime <= 0 && this.shotgunRemainBullet > 0) {
                    initEffect();
                    this.gameViewBase.playSound(8, 1.0f, 0.8f, 1, 0, 1.0f);
                    if (GameObjectManager.getInstance() != null) {
                        Point[] sightVecs = new Point[shotgunPointOfHit.length];
                        float azimuth = GLRenderer.getAzimuth();
                        float pitch = GLRenderer.getPitch();
                        for (int i = 0; i < shotgunPointOfHit.length; i++) {
                            PointOfHit pointOfHit = shotgunPointOfHit[i];
                            sightVecs[i] = new Point(getSightVector((pointOfHit.getPointX() / 10.0f) + azimuth, (pointOfHit.getPointY() / 10.0f) + pitch));
                        }
                        for (Point sightVec : sightVecs) {
                            List<GameObject> hitGameObject = GLRenderer.sortGameObject((ArrayList) GameObjectManager.getInstance().getInSightEnemyObjects(sightVec, this.shootgunHitDegree), true);
                            Iterator<GameObject> it = hitGameObject.iterator();
                            while (true) {
                                if (!it.hasNext()) {
                                    break;
                                }
                                GameObject obj = it.next();
                                if (obj.isAlive()) {
                                    GameObjectManager.getInstance().createHitEvent(obj);
                                }
                            }
                        }
                        this.shotgunCoolDownStartTime = System.currentTimeMillis();
                    }
                    if (this.shotgunRemainBullet > 0) {
                        this.shotgunRemainBullet--;
                        break;
                    }
                }
                break;
            case 2:
                for (int i2 = 0; i2 < 4; i2++) {
                    HomingLaserWeaponObject homingLaser = homingLasers[i2];
                    if (homingLaser != null && homingLaser.getStatus() == 2) {
                        this.gameViewBase.playSound(9, 0.7f, 0.7f, 1, 0, 1.0f);
                        homingLaser.shoot();
                        homingLasers[i2] = null;
                        this.homingLaserCoolDownStartTime = System.currentTimeMillis();
                    }
                }
                break;
            case 3:
                if (GameObjectManager.getInstance() != null) {
                    for (GameObject obj2 : GameObjectManager.getInstance().getDisplayObjects()) {
                        if (obj2.isAlive()) {
                            GameObjectManager.getInstance().createHitEvent(obj2);
                        }
                    }
                    break;
                }
                break;
        }
    }

    private void lockOn() {
        if (this.currentWeapon != 2) {
            clearLockOn();
            return;
        }
        if (this.homingLaserCoolDownStartTime <= 0 || System.currentTimeMillis() >= this.homingLaserCoolDownStartTime + 2000) {
            for (int i = 0; i < 4; i++) {
                if (homingLasers[i] != null && homingLasers[i].getStatus() < 2) {
                    homingLasers[i].setStatus(0);
                }
            }
            float degree = MISSILE_SIGHT_DEFAULT_DEGREE * this.sightSizeRatio;
            if (GameObjectManager.getInstance() != null) {
                for (GameObject obj : GameObjectManager.getInstance().getInSightEnemyObjects(new Point(GLRenderer.getSightVector()), degree)) {
                    if (obj.isAlive()) {
                        boolean isNewTarget = true;
                        int i2 = 0;
                        while (true) {
                            if (i2 >= 4) {
                                break;
                            }
                            if (homingLasers[i2] == null || obj.getObjectId() != homingLasers[i2].getTargetObject().getObjectId()) {
                                i2++;
                            } else {
                                homingLasers[i2].setStatus(1);
                                isNewTarget = false;
                                break;
                            }
                        }
                        if (isNewTarget) {
                            int i3 = 0;
                            while (true) {
                                if (i3 >= 4) {
                                    break;
                                }
                                if (homingLasers[i3] != null) {
                                    i3++;
                                } else {
                                    float baseX = (i3 + 1) * 2;
                                    double radians = Math.toRadians(GLRenderer.getAzimuth());
                                    float rotateX = (float) ((Math.cos(radians) * baseX) - (Math.sin(radians) * 0.0f));
                                    float rotateZ = (float) ((Math.sin(radians) * baseX) + (Math.cos(radians) * 0.0f));
                                    homingLasers[i3] = new HomingLaserWeaponObject(200, 0, new MissileBehaviorPattern(new Point(rotateX, -5.0f, rotateZ), MISSILE_SPEED, 50, MISSILE_MAX_CURVE_DEGREE, obj), 100L, 10, 2000);
                                    homingLasers[i3].setStatus(1);
                                    homingLasers[i3].startLockOn();
                                    homingLasers[i3].setLockOnCompleteEventListner(this);
                                    GameObjectManager.getInstance().addGameObject(homingLasers[i3]);
                                    break;
                                }
                            }
                        }
                    }
                }
            }
            for (int i4 = 0; i4 < 4; i4++) {
                if (homingLasers[i4] != null && (homingLasers[i4].getStatus() == 0 || !homingLasers[i4].getTargetObject().isAlive())) {
                    homingLasers[i4].stopLockOn();
                    homingLasers[i4] = null;
                }
            }
        }
    }

    private void clearLockOn() {
        for (int i = 0; i < 4; i++) {
            if (homingLasers[i] != null) {
                homingLasers[i].stopLockOn();
                homingLasers[i] = null;
            }
        }
        this.homingLaserCoolDownStartTime = 0L;
    }

