public class DamageDisp {
    private float baseY;
    private float currentDisplayY;
    private Bitmap damageSecBitmap;
    private final long dispSpan;
    private final float downDistance;
    private long dispStartTime = 0;
    private boolean isSet = false;

    public DamageDisp(Context context, long dispSpan, float maxDownDistance) {
        this.dispSpan = dispSpan;
        this.downDistance = maxDownDistance;
    }

    public void initialize(int damageSec, float baseY) {
        this.baseY = baseY;
        this.dispStartTime = 0L;
        this.currentDisplayY = 0.0f;
        if (damageSec > 0 && damageSec < 10) {
            this.damageSecBitmap = GameResources.numbersRed[damageSec];
        } else {
            this.damageSecBitmap = null;
        }
        if (this.damageSecBitmap == null) {
            this.isSet = false;
        } else {
            this.isSet = true;
        }
    }

    public void drawDamageSec(Canvas canvas) {
        if (this.isSet) {
            if (this.dispStartTime == 0) {
                this.dispStartTime = System.currentTimeMillis();
            }
            long pastTime = System.currentTimeMillis() - this.dispStartTime;
            float ratio = pastTime / this.dispSpan;
            if (ratio > 1.0f) {
                this.isSet = false;
                this.dispStartTime = 0L;
            } else {
                this.currentDisplayY = this.baseY + (this.downDistance * ratio);
                GameContoroller.drawBitmapOnCanvas(GameResources.numberMinusRed, (GameResources.centerX - GameResources.numberMinusRed.getWidth()) - GameResources.numbersRed[0].getWidth(), this.currentDisplayY, (Paint) null, canvas);
                GameContoroller.drawBitmapOnCanvas(this.damageSecBitmap, GameResources.centerX - GameResources.numbersRed[0].getWidth(), this.currentDisplayY, (Paint) null, canvas);
                GameContoroller.drawBitmapOnCanvas(GameResources.secRed, GameResources.centerX, this.currentDisplayY, (Paint) null, canvas);
            }
        }
    }

    public float getCurrentDisplayY() {
        return this.currentDisplayY;
    }
}

