        if (this.flg_music && !this.isPlayingMusic) {
            try {
                this.player = MediaPlayer.create(context, resId);
                this.player.setLooping(true);
                this.player.seekTo(0);
                this.player.start();
                this.isPlayingMusic = true;
            } catch (Exception e) {
            }
        }
    }

    public synchronized void pauseBGM() {
        if (this.flg_music && this.player != null) {
            this.player.pause();
        }
    }

