        if (this.flg_music && this.player != null) {
            this.player.start();
        }
    }

    public synchronized void stopBGM() {
        if (this.isPlayingMusic && this.player != null) {
            this.player.stop();
            this.player.release();
            this.isPlayingMusic = false;
            this.player = null;
        }
    }

