public class ChaseAndEscapeBehaviorPattern implements BehaviorPattern {
    private static final Point USER_POINT = new Point(0.0f, 0.0f, 0.0f);
    private Destination currentDestination;
    private float longOfSight;
    private float longOfUser;
    private int reactionInterval;
    private int speed;
    private long timeOfCreatedCurrentDistination = 0;

    public ChaseAndEscapeBehaviorPattern(Point startPoint, int speed, int reactionInterval, float longOfUser, float longOfSight) {
        this.speed = speed;
        this.reactionInterval = reactionInterval;
        this.longOfUser = longOfUser;
        this.longOfSight = longOfSight;
        this.currentDestination = new Destination(0, startPoint, USER_POINT, speed);
    }

    @Override // jp.co.questcom.droidshooting.game.object.BehaviorPattern
    public Destination getNextDestination() {
        long now = System.currentTimeMillis();
        if (now - this.timeOfCreatedCurrentDistination < this.reactionInterval / 2) {
            return this.currentDestination;
        }
        this.timeOfCreatedCurrentDistination = now;
        float[] sightArr = GLRenderer.getSightVector();
        Point sightVec = new Point(sightArr[0], sightArr[1], sightArr[2]);
        Point tmpNext = CoordinatesCalculationUtil.calculatePointByPixels(USER_POINT, sightVec, this.longOfUser, false);
        float[] sightRatio = CoordinatesCalculationUtil.m0get(USER_POINT, sightVec);
        float reviseDistance = this.longOfSight;
        float xDistance = this.currentDestination.getPosition().getX() - tmpNext.getX();
        float yDistance = this.currentDestination.getPosition().getY() - tmpNext.getY();
        float zDistance = this.currentDestination.getPosition().getZ() - tmpNext.getZ();
        float xReviseDistance = xDistance < 0.0f ? -reviseDistance : reviseDistance;
        float yReviseDistance = yDistance < 0.0f ? -reviseDistance : reviseDistance;
        float zReviseDistance = zDistance < 0.0f ? -reviseDistance : reviseDistance;
        tmpNext.setX(tmpNext.getX() + (sightRatio[0] * xReviseDistance));
        tmpNext.setY(tmpNext.getY() + (sightRatio[1] * yReviseDistance));
        tmpNext.setZ(tmpNext.getZ() + (sightRatio[2] * zReviseDistance));
        Point next = CoordinatesCalculationUtil.calculatePointByTime(this.currentDestination.getPosition(), tmpNext, this.speed, this.reactionInterval, true);
        Destination ret = new Destination(this.currentDestination.getIndex() + 1, next, USER_POINT, this.speed);
        this.currentDestination = ret;
        return ret;
    }

    @Override // jp.co.questcom.droidshooting.game.object.BehaviorPattern
    public ChaseAndEscapeBehaviorPattern clone() {
        ChaseAndEscapeBehaviorPattern ret = null;
        try {
            ret = (ChaseAndEscapeBehaviorPattern) super.clone();
        } catch (CloneNotSupportedException e) {
            e.printStackTrace();
        }
        ret.currentDestination = this.currentDestination.clone();
        return ret;
    }
}

