    protected void onHit(int damage) {
        super.onHit(damage);
        ExplosionEffect explosionEffect = ExplosionEffect.getInstance();
        explosionEffect.setTexIndex(0);
        Log.i("onHit", "ObjectId:" + getObjectId());
        this.currentHitPoint -= damage;
        if (this.currentHitPoint <= 0) {
            if (getDroidType() == 3) {
                explosionEffect.setSize(3.0f);
            } else if (getDroidType() == 2) {
                explosionEffect.setSize(2.0f);
            } else {
                explosionEffect.setSize(1.0f);
            }
        } else if (getDroidType() == 3) {
            explosionEffect.setSize(0.9f);
        } else if (getDroidType() == 2) {
            explosionEffect.setSize(0.6f);
        } else {
            explosionEffect.setSize(0.3f);
        }
        addEffect(explosionEffect);
    }

    private static int getHitpoint(int orgHitpoint, int stageNumber) {
        int value = (stageNumber + 1) / 10;
        if (value <= 0) {
            return orgHitpoint;
        }
        double coefficient = 1.0d;
        for (int i = 0; i < value; i++) {
            coefficient += 0.35d;
        }
        int hitpoint = (int) (orgHitpoint * coefficient);
        return hitpoint;
    }

    private static int getSpeed(int orgSpeed, int stageNumber) {
        int value = (stageNumber + 1) / 10;
        if (value <= 0) {
            return orgSpeed;
        }
        double coefficient = 1.0d;
        for (int i = 0; i < value; i++) {
            coefficient += 0.2d;
        }
        int speed = (int) (orgSpeed * coefficient);
        return speed;
    }

