    private Point getEscapePoint(Point currentPoint) {
        float[] sightArr = GLRenderer.getSightVector();
        Point sightVec = new Point(sightArr[0], sightArr[1], sightArr[2]);
        float longOfUser = Math.abs(currentPoint.getX()) + Math.abs(currentPoint.getY()) + Math.abs(currentPoint.getZ());
        float longOfSight = longOfUser / 2.0f;
        Point ret = currentPoint.clone();
        float[] sightRatio = CoordinatesCalculationUtil.m0get(USER_VIEW_POINT, sightVec);
        float xDistance = currentPoint.getX() - ret.getX();
        float yDistance = currentPoint.getY() - ret.getY();
        float zDistance = currentPoint.getZ() - ret.getZ();
        float xReviseDistance = xDistance < 0.0f ? -longOfSight : longOfSight;
        float yReviseDistance = yDistance < 0.0f ? -longOfSight : longOfSight;
        float zReviseDistance = zDistance < 0.0f ? -longOfSight : longOfSight;
        ret.setX(ret.getX() + (sightRatio[0] * xReviseDistance));
        ret.setY(ret.getY() + (sightRatio[1] * yReviseDistance));
        ret.setZ(ret.getZ() + (sightRatio[2] * zReviseDistance));
        return ret;
    }
