    protected boolean isDisplay(Point pos, int sightDegree) {
        float[] lookAtVec = GLRenderer.getSightVector();
        if (lookAtVec == null) {
            return false;
        }
        float lookX = lookAtVec[0];
        float lookY = lookAtVec[1];
        float lookZ = lookAtVec[2];
        if (lookY > 0.8d || lookY < -0.8d) {
            return true;
        }
        double lookAtan = Math.atan2(lookX, lookZ);
        double objAtan = Math.atan2(pos.getX(), pos.getZ());
        double lookAngle = lookAtan * 57.29577951308232d;
        double objAngle = objAtan * 57.29577951308232d;
        if (lookAngle < 0.0d) {
            lookAngle += 360.0d;
        }
        if (objAngle < 0.0d) {
            objAngle += 360.0d;
        }
        double min = Math.min(lookAngle, objAngle);
        double max = Math.max(lookAngle, objAngle);
        if (max - min < sightDegree || max - min > 360 - sightDegree) {
            return true;
        }
        return false;
    }

