        float xRatio = loopAngle.getX() / allRatio;
        float yRatio = loopAngle.getY() / allRatio;
        float zRatio = loopAngle.getZ() / allRatio;
        float maxRatio = Math.max(xRatio, Math.max(yRatio, zRatio));
