            double cos = Math.cos(radians) * radius;
            double x = xRatio * cos;
            double y = yRatio * sin;
            double zSinRatio = zRatio - yRatio;
            double zCosRatio = zRatio - xRatio;
            if (zSinRatio < 0.0d) {
                zSinRatio = 0.0d;
            }
            double sin2 = sin * zSinRatio;
            if (zCosRatio < 0.0d) {
                zCosRatio = 0.0d;
            }
            double z = sin2 + (cos * zCosRatio);
            Point position = new Point(((float) (reviseRatio * x)) + centerPoint.getX(), ((float) (reviseRatio * y)) + centerPoint.getY(), ((float) (reviseRatio * z)) + centerPoint.getZ());
            if (direction == DirectionMode.Ahead) {
                vector = new Point(position.getX() * 2.0f, position.getY() * 2.0f, position.getZ() * 2.0f);
            } else if (direction == DirectionMode.CircleCenter) {
