    public List<GameObject> getDrawGameObjects() {
        List<GameObject> ret = new ArrayList<>();
        ret.addAll(this.allocateObjects);
        if (this.allGameObjectSets != null && this.currentObjectSetIndex < this.allGameObjectSets.size()) {
            List<GameObject> set = this.allGameObjectSets.get(this.currentObjectSetIndex);
            int cnt = 0;
            for (GameObject obj : set) {
                ret.add(obj);
                if ((obj instanceof EnemyGameObject) && obj.isAlive()) {
                    cnt++;
                }
            }
            if (cnt == 0 && this.currentObjectSetIndex + 1 < this.allGameObjectSets.size()) {
                long now = System.currentTimeMillis();
                if (this.currentObjectSetDeadTime == -1) {
                    this.currentObjectSetDeadTime = now;
                }
                if (this.currentObjectSetDeadTime + 1000 < now) {
                    ret.clear();
                    List<List<GameObject>> list = this.allGameObjectSets;
                    int i = this.currentObjectSetIndex + 1;
                    this.currentObjectSetIndex = i;
                    ret.addAll(list.get(i));
                    this.currentObjectSetDeadTime = -1L;
                }
            }
        }
        return ret;
    }

