    public static final int STATUS_IS_SHOOT = 3;
    public static final int STATUS_LOCKING_ON = 1;
    public static final int STATUS_LOCK_ON_COMPLETE = 2;
    public static final int STATUS_NOT_LOCK_ON = 0;
    private int damage;
    private int homingTime;
    private boolean isLockOnComplete;
    private boolean isLockOnStart;
    private List<LockOnEventListner> lockOnEventListners;
    private LockOnMarker lockOnMarker;
    private LockOnMarker lockOnMarkerComp;
    private long lockOnStartTime;
    private long lockOnTime;
    private MissileBehaviorPattern pattern;
    private long shootTime;
    private int status;

    public HomingLaserWeaponObject(int hitPoint, int speed, MissileBehaviorPattern pattern, long lockOnTime, int damage, int homingTime) {
        super(hitPoint, speed, pattern);
        this.status = 0;
        this.isLockOnStart = false;
        this.isLockOnComplete = false;
        this.lockOnMarker = new LockOnMarker();
        this.lockOnMarkerComp = new LockOnMarker();
        this.lockOnEventListners = new ArrayList();
        this.pattern = pattern;
        this.lockOnTime = lockOnTime;
        EnemyGameObject target = (EnemyGameObject) pattern.getTargetObject();
        target.addEffect(this.lockOnMarker);
        target.addEffect(this.lockOnMarkerComp);
        this.damage = damage;
        this.homingTime = homingTime;
    }

    @Override // jp.co.questcom.droidshooting.game.object.IWeapon
    public void shoot() {
        this.shootTime = System.currentTimeMillis();
        this.status = 3;
        stopLockOn();
    }

    @Override // jp.co.questcom.droidshooting.game.object.EnemyGameObject, jp.co.questcom.droidshooting.game.object.GameObject
    public void draw(GL10 gl) {
        switch (this.status) {
            case 1:
                this.lockOnMarker.setTexIndex(4);
                if (!this.isLockOnStart) {
                    for (LockOnEventListner listner : this.lockOnEventListners) {
                        listner.onLockOnStart();
                    }
                    this.isLockOnStart = true;
                    break;
                }
                break;
            case 2:
                this.lockOnMarkerComp.setTexIndex(5);
                if (!this.isLockOnComplete) {
                    for (LockOnEventListner listner2 : this.lockOnEventListners) {
                        listner2.onLockOnComplete();
                    }
                    this.isLockOnComplete = true;
                    break;
                }
                break;
            case 3:
                if (isAlive() && System.currentTimeMillis() > this.shootTime + this.homingTime) {
                    this.currentHitPoint = 0;
                }
                if (isAlive()) {
                    GameObject hitObj = null;
                    try {
                        Iterator<GameObject> it = GameObjectManager.getInstance().getAliveEnemyGameObjects().iterator();
                        while (true) {
                            if (it.hasNext()) {
                                GameObject obj = it.next();
                                if (CoordinatesCalculationUtil.getVectorLength(obj.getCurrentPosition(), getCurrentPosition()) <= 2.0d) {
                                    hitObj = obj;
                                }
                            }
                        }
                    } catch (ConcurrentModificationException e) {
                    }
                    if (hitObj != null) {
                        GameObjectManager.getInstance().createHitEvent(hitObj, this.damage);
                        ExplosionEffect explosionEffect = ExplosionEffect.getInstance();
                        explosionEffect.setTexIndex(3);
                        if (hitObj instanceof DroidEnemyGameObject) {
                            if (((DroidEnemyGameObject) hitObj).getDroidType() == 3) {
                                explosionEffect.setSize(7.0f);
                            } else if (((DroidEnemyGameObject) hitObj).getDroidType() == 2) {
                                explosionEffect.setSize(5.0f);
                            } else {
                                explosionEffect.setSize(3.5f);
                            }
                        }
                        if (hitObj instanceof EnemyGameObject) {
                            ((EnemyGameObject) hitObj).addEffect(explosionEffect);
                        }
                        this.currentHitPoint = 0;
                        break;
                    } else {
                        super.draw(gl);
                        break;
                    }
                }
                break;
        }
    }

