    private void createParticles(float size, int lifeSpan, float downMoveY, float reducationRatio) {
        Particle[] particles = this.mParticles;
        Random rand = new Random(System.currentTimeMillis());
        float x = rand.nextFloat() - 0.5f;
        float y = rand.nextFloat() - 0.5f;
        float z = rand.nextFloat() - 0.5f;
        float moveX = (rand.nextFloat() - 0.5f) * 0.02f;
        float moveY = (rand.nextFloat() - 0.5f) * 0.02f;
        float moveZ = (rand.nextFloat() - 0.5f) * 0.02f;
        int i = 0;
        while (true) {
            if (i >= 1) {
                break;
            }
            if (particles[i].mIsActive) {
                i++;
            } else {
                particles[i].mIsActive = true;
                particles[i].mX = x;
                particles[i].mY = y;
                particles[i].mZ = z;
                particles[i].mMoveX = moveX;
                particles[i].mMoveY = moveY;
                particles[i].mMoveZ = moveZ;
                particles[i].mSize = size;
                particles[i].mLifeSpan = lifeSpan;
                particles[i].mDownMoveY = downMoveY;
                particles[i].mReducationRatio = reducationRatio;
                particles[i].mFrameNumber = 0;
                particles[i].init();
                break;
            }
        }
        this.mFrameNumber = 0;
    }

