    public void draw(GL10 gl) {
        if (this.mFrameNumber < this.startSpan) {
            this.mFrameNumber++;
            return;
        }
        updateParticles();
        Particle[] particles = this.mParticles;
        boolean isDraw = false;
        for (int i = 0; i < 1; i++) {
            if (particles[i].mIsActive) {
                gl.glPushMatrix();
                gl.glLoadIdentity();
                particles[i].draw(gl, this.position, this.rotateVec, this.rotateAngle, this.targetTex);
                gl.glPopMatrix();
                isDraw = true;
            }
        }
        this.isStillDraw = isDraw;
    }

