            Log.e("ProgramableBehaviorPattern", "目的地が定義されていません。");
            return new Destination();
        }
        if (this.currentDestinationIndex == -1) {
            this.currentDestinationIndex = 0;
            this.preDestination = new Destination(this.destinations[0].getIndex(), this.destinations[0].getPosition(), null, this.destinations[0].getSpeed());
            return this.destinations[0].clone();
        }
        Destination currentDestination = this.destinations[this.currentDestinationIndex];
        if (this.preDestination.getPosition().equals(currentDestination.getPosition())) {
            int i = this.currentDestinationIndex + 1;
            this.currentDestinationIndex = i;
            int nextIndex = i % this.destinations.length;
            this.currentDestinationIndex = nextIndex;
            currentDestination = this.destinations[this.currentDestinationIndex];
        }
        Point tmpNextPont = CoordinatesCalculationUtil.calculatePointByTime(this.preDestination.getPosition(), currentDestination.getPosition(), currentDestination.getSpeed(), 500L, true);
        Point nextPoint = tmpNextPont;
        if (this.preDestination.getVector() != null && !tmpNextPont.equals(currentDestination.getPosition())) {
            float angleForTarget = (float) Math.abs(CoordinatesCalculationUtil.CalcTurningAngle(this.preDestination.getPosition(), this.preDestination.getVector(), tmpNextPont));
            if (angleForTarget > this.limitAngle && angleForTarget != 180.0f) {
                Point revisionPoint = Point.sub(tmpNextPont, this.preDestination.getVector());
                float ratio = this.limitAngle / angleForTarget;
                revisionPoint.setX(revisionPoint.getX() * ratio);
                revisionPoint.setY(revisionPoint.getY() * ratio);
                revisionPoint.setZ(revisionPoint.getZ() * ratio);
                nextPoint = Point.add(this.preDestination.getVector(), revisionPoint);
            }
        }
        Point nextVec = CoordinatesCalculationUtil.calculatePointByTime(this.preDestination.getPosition(), nextPoint, currentDestination.getSpeed(), 1000L, false);
        Destination ret = new Destination(this.preDestination.getIndex() + 1, nextPoint, nextVec, currentDestination.getSpeed());
        this.preDestination = ret;
        return ret;
