    public void onClick(View v) {
        long targetStageNumber;
        long targetStageNumber2;
        if (v == this.btnStartGame) {
            Intent intent = new Intent(this.titleActivity, (Class<?>) CameraActivity.class);
            intent.putExtra("jp.co.questcom.droidshooting.stage", 0);
            intent.putExtra("jp.co.questcom.droidshooting.score", 0L);
            this.titleActivity.startActivity(intent);
            return;
        }
        if (v == this.btnStartWave) {
            Intent intent2 = new Intent(this.titleActivity, (Class<?>) CameraActivity.class);
            intent2.putExtra("jp.co.questcom.droidshooting.stage", Long.valueOf(getStageNumber()));
            intent2.putExtra("jp.co.questcom.droidshooting.score", 0L);
            this.titleActivity.startActivity(intent2);
            return;
        }
        if (v == this.btnPrevArrow) {
            this.arrowButtonEventlistner.onClickArrowButtonEventListner(this.index - 1);
            return;
        }
        if (v == this.btnNextArrow) {
            this.arrowButtonEventlistner.onClickArrowButtonEventListner(this.index + 1);
            return;
        }
        if (v == this.btnPrevDoubleArrow) {
            if (getStageNumber() - 5 < 0) {
                targetStageNumber2 = 0;
            } else {
                targetStageNumber2 = getStageNumber() - 5;
            }
            this.arrowButtonEventlistner.onClickArrowButtonEventListner(convertToIndex(targetStageNumber2));
            return;
        }
        if (v == this.btnNextDoubleArrow) {
            if (getStageNumber() + 5 > this.titleActivity.maxStageNumber) {
                targetStageNumber = this.titleActivity.maxStageNumber;
            } else {
                targetStageNumber = getStageNumber() + 5;
            }
            this.arrowButtonEventlistner.onClickArrowButtonEventListner(convertToIndex(targetStageNumber));
            return;
        }
        if (v == this.iconExclamation) {
            this.iconClickEventListner.onExclamationClick();
            return;
        }
        if (v == this.iconQuestion) {
            this.iconClickEventListner.onQuestionClick();
        } else if (v == this.iconReturn) {
            this.iconClickEventListner.onReturnTitleClick();
        } else if (v == this.iconShare) {
            this.iconClickEventListner.onShareClick();
        }
    }

