    public void onDraw(Canvas canvas) {
        canvas.drawColor(Color.argb(0, 0, 0, 0));
        if (this.isRogoAlreadyDisplay) {
            long elapsed = System.currentTimeMillis() - this.startTime;
            canvas.drawBitmap(GameResources.title_center, (getWidth() / 2) - (GameResources.title_center.getWidth() / 2), ((getHeight() / 2) - (GameResources.title_center.getHeight() / 2)) - 40, (Paint) null);
            canvas.save();
            canvas.rotate(elapsed * 0.02f, getWidth() / 2, (getHeight() / 2) - 40);
            canvas.drawBitmap(GameResources.title_char, (getWidth() / 2) - (GameResources.title_char.getWidth() / 2), ((getHeight() / 2) - (GameResources.title_char.getHeight() / 2)) - 40, (Paint) null);
            canvas.restore();
            if (System.currentTimeMillis() - this.startTime > 1000 && !this.is_play_logo_1_sound) {
                this.gameViewBase.playSound(0, 0.5f, 0.4f, 1, 0, 1.0f);
                this.is_play_logo_1_sound = true;
            }
            if (System.currentTimeMillis() - this.startTime > 1300) {
                if (this.logo_1_dispcount <= 0) {
                    canvas.drawBitmap(GameResources.title_logo_1, this.logo1DisplayPoint.x, this.logo1DisplayPoint.y, (Paint) null);
                } else {
                    int slidePoint = this.logo_1_dispcount * this.logo_1_dispcount;
                    canvas.drawBitmap(GameResources.title_logo_1, this.logo1DisplayPoint.x - slidePoint, this.logo1DisplayPoint.y, (Paint) null);
                    this.logo_1_dispcount--;
                }
            }
            if (System.currentTimeMillis() - this.startTime > 1600 && !this.is_play_logo_2_sound) {
                this.gameViewBase.playSound(0, 0.5f, 0.4f, 1, 0, 1.0f);
                this.is_play_logo_2_sound = true;
            }
            if (System.currentTimeMillis() - this.startTime > 2000) {
                if (this.logo_2_dispcount <= 0) {
                    canvas.drawBitmap(GameResources.title_logo_2, this.logo2DisplayPoint.x, this.logo2DisplayPoint.y, (Paint) null);
                } else {
                    int slidePoint2 = this.logo_2_dispcount * this.logo_2_dispcount;
                    canvas.drawBitmap(GameResources.title_logo_2, this.logo2DisplayPoint.x + slidePoint2, this.logo2DisplayPoint.y, (Paint) null);
                    this.logo_2_dispcount--;
                }
            }
            if (this.logo_2_dispcount <= 0 && !this.isShownDialog) {
                if (this.member == null || TextUtils.isEmpty(this.member.getName())) {
                    this.titleActivity.showEditNameDialog();
                }
                this.isShownDialog = true;
            }
        }
    }

