public class TotalScore {
    private int bronzeMedals;
    private int goldMedals;
    private Member member;
    private long score;
    private int silverMedals;

    public TotalScore(String name, String country, long score, int goldMedals, int silverMedals, int bronzeMedals, long updated) {
        this.member = new Member();
        this.member.setName(name);
        this.member.setLocale(new Locale("", country));
        this.member.setUpdated(updated);
        this.score = score;
        this.goldMedals = goldMedals;
        this.silverMedals = silverMedals;
        this.bronzeMedals = bronzeMedals;
    }

    public TotalScore() {
        DBHelper dbHelper = new DBHelper();
        SQLiteDatabase db = null;
        Cursor c = null;
        try {
            db = dbHelper.getReadableDatabase();
            c = db.query(DBHelper.SCORE_TABLE, new String[]{"max(score), sum(gold), sum(silver), sum(bronze)"}, null, null, "round", null, null, null);
            while (c.moveToNext()) {
                this.score += c.getLong(0);
                if (c.getLong(1) > 0) {
                    this.goldMedals++;
                } else if (c.getLong(2) > 0) {
                    this.silverMedals++;
                } else if (c.getLong(3) > 0) {
                    this.bronzeMedals++;
                }
            }
        } finally {
            if (c != null) {
                c.close();
            }
            if (db != null) {
                db.close();
            }
        }
    }

